local function murloc(ctx,e)for _,t in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags)do if t=="murloc"or t=="all"then return true end end return false end
return {api_version=1,id="NEW1_017",name="Hungry Crab",text="<b>Battlecry:</b> Destroy a Murloc and gain +2/+2.",set="EXPERT1",type="minion",rarity="epic",cost=1,attack=1,health=2,tags={"beast"},keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx)local r={};for _,e in ipairs(ctx:minions())do if murloc(ctx,e)then r[#r+1]=e end end;return r end,on_battlecry=function(ctx,self,target)if target then cardlib.effects.destroy(ctx, target);ctx:buff(self,2,2)end end}
